{"command":"cat << 'EOF' > src/config.py
import os
import sys
import fnmatch
from pathlib import Path
from rule_defaults import DEFAULT_RULE_CONFIGS

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

DEFAULT_GLOBAL_CONFIG = {
    "enable": [],
    "disable": [],
    "exclude": [],
    "include": [],
    "respect-gitignore": True,
    "line-length": 80,
    "fixable": [],
    "unfixable": [],
    "flavor": "standard",
    "force-exclude": False,
    "cache": True
}

DEFAULT_CODE_BLOCK_TOOLS = {
    "enabled": False,
    "normalize-language": "linguist",
    "on-error": "fail",
    "on-missing-language-definition": "ignore",
    "on-missing-tool-binary": "ignore",
    "timeout": 30000,
    "languages": {},
    "language-aliases": {},
    "tools": {}
}

class Config:
    def __init__(self, config_path=None, ignore_config=False):
        self.config_path = None
        self.global_config = dict(DEFAULT_GLOBAL_CONFIG)
        self.per_file_ignores = {}
        self.per_file_flavor = {}
        self.code_block_tools = dict(DEFAULT_CODE_BLOCK_TOOLS)
        self.rule_configs = {k: dict(v) for k, v in DEFAULT_RULE_CONFIGS.items()}
        self.loaded_file = None

        if not ignore_config:
            self._load(config_path)

    def _load(self, custom_path=None):
        target = None
        if custom_path:
            p = Path(custom_path).resolve()
            if p.is_file():
                target = p
        else:
            cwd = Path.cwd()
            for name in [".rumdl.toml", "pyproject.toml"]:
                p = cwd / name
                if p.is_file():
                    target = p
                    break

        if not target or not target.is_file() or tomllib is None:
            return

        try:
            with open(target, "rb") as f:
                data = tomllib.load(f)
            self.loaded_file = str(target)

            if target.name == "pyproject.toml":
                data = data.get("tool", {}).get("rumdl", {})

            # Parse global settings
            if "global" in data and isinstance(data["global"], dict):
                g = data["global"]
                for k, v in g.items():
                    key = k.replace("_", "-")
                    self.global_config[key] = v
            else:
                # Top level keys in pyproject or .rumdl.toml
                for k, v in data.items():
                    if k not in ["global", "per-file-ignores", "per-file-flavor", "code-block-tools"] and not k.startswith("MD"):
                        key = k.replace("_", "-")
                        self.global_config[key] = v

            if "per-file-ignores" in data and isinstance(data["per-file-ignores"], dict):
                self.per_file_ignores = data["per-file-ignores"]
            elif "per_file_ignores" in data and isinstance(data["per_file_ignores"], dict):
                self.per_file_ignores = data["per_file_ignores"]

            if "per-file-flavor" in data and isinstance(data["per-file-flavor"], dict):
                self.per_file_flavor = data["per-file-flavor"]
            elif "per_file_flavor" in data and isinstance(data["per_file_flavor"], dict):
                self.per_file_flavor = data["per_file_flavor"]

            if "code-block-tools" in data and isinstance(data["code-block-tools"], dict):
                self.code_block_tools.update(data["code-block-tools"])

            # Rule specific configs
            for k, v in data.items():
                if k.startswith("MD") and isinstance(v, dict):
                    sec = k.upper()
                    if sec not in self.rule_configs:
                        self.rule_configs[sec] = {}
                    for rk, rv in v.items():
                        rkey = rk.replace("_", "-")
                        self.rule_configs[sec][rkey] = rv
        except Exception:
            pass
EOF"}

