import json
import xml.etree.ElementTree as ET

def format_diagnostics(diagnostics, format_name="text", file_count=1, elapsed_ms=10, is_fmt=False, fixed_count=0, total_count=0):
    if format_name == "json":
        res = []
        for d in diagnostics:
            item = {
                "file": d["file"],
                "line": d["line"],
                "column": d["column"],
                "rule": d["rule"],
                "message": d["message"],
                "severity": d.get("severity", "warning"),
                "fixable": d.get("fixable", False),
                "fix": d.get("fix")
            }
            res.append(item)
        return json.dumps(res, indent=2)

    elif format_name == "json-lines":
        lines = []
        for d in diagnostics:
            item = {
                "file": d["file"],
                "line": d["line"],
                "column": d["column"],
                "rule": d["rule"],
                "message": d["message"],
                "severity": d.get("severity", "warning"),
                "fixable": d.get("fixable", False)
            }
            lines.append(json.dumps(item))
        out = "\n".join(lines)
        if diagnostics:
            out += "\n\n"
        out += format_summary(diagnostics, file_count, elapsed_ms, is_fmt, fixed_count, total_count)
        return out

    elif format_name in ("text", "full"):
        lines = []
        for d in diagnostics:
            fix_mark = " [*]" if d.get("fixable") and not is_fmt else (" [fixed]" if d.get("fixed") else "")
            lines.append(f"{d['file']}:{d['line']}:{d['column']}: [{d['rule']}] {d['message']}{fix_mark}")
        out = "\n".join(lines)
        if diagnostics:
            out += "\n\n"
        out += format_summary(diagnostics, file_count, elapsed_ms, is_fmt, fixed_count, total_count)
        return out

    elif format_name == "concise":
        lines = []
        for d in diagnostics:
            lines.append(f"{d['file']}:{d['line']}:{d['column']}: [{d['rule']}] {d['message']}")
        out = "\n".join(lines)
        if diagnostics:
            out += "\n\n"
        out += format_summary(diagnostics, file_count, elapsed_ms, is_fmt, fixed_count, total_count)
        return out

    elif format_name == "grouped":
        grouped = {}
        for d in diagnostics:
            f = d["file"]
            r = d["rule"]
            grouped.setdefault(f, {}).setdefault(r, []).append(d)
        lines = []
        for f, rules in grouped.items():
            lines.append(f"{f}:")
            for r, items in rules.items():
                lines.append(f"  {r}:")
                for d in items:
                    fix_str = " (fixable)" if d.get("fixable") else ""
                    lines.append(f"    {d['line']}:{d['column']} {d['message']}{fix_str}")
        out = "\n".join(lines)
        if diagnostics:
            out += "\n\n"
        out += format_summary(diagnostics, file_count, elapsed_ms, is_fmt, fixed_count, total_count)
        return out

    elif format_name == "github":
        lines = []
        for d in diagnostics:
            sev = d.get("severity", "warning")
            lines.append(f"::{sev} file={d['file']},line={d['line']},col={d['column']},endLine={d['line']},endColumn={d['column']+10},title={d['rule']}::{d['message']}")
        out = "\n".join(lines)
        if diagnostics:
            out += "\n\n"
        out += format_summary(diagnostics, file_count, elapsed_ms, is_fmt, fixed_count, total_count)
        return out

    elif format_name == "gitlab":
        res = []
        for d in diagnostics:
            res.append({
                "description": d["message"],
                "check_name": d["rule"],
                "fingerprint": f"{d['file']}-{d['line']}-{d['column']}-{d['rule']}",
                "severity": "minor",
                "location": {
                    "path": d["file"],
                    "lines": {
                        "begin": d["line"]
                    }
                }
            })
        return json.dumps(res, indent=2)

    elif format_name == "pylint":
        lines = []
        for d in diagnostics:
            lines.append(f"{d['file']}:{d['line']}:{d['column']}: [C{d['rule']}] {d['message']}")
        out = "\n".join(lines)
        if diagnostics:
            out += "\n\n"
        out += format_summary(diagnostics, file_count, elapsed_ms, is_fmt, fixed_count, total_count)
        return out

    elif format_name == "azure":
        lines = []
        for d in diagnostics:
            sev = d.get("severity", "warning")
            lines.append(f"##vso[task.logissue type={sev};sourcepath={d['file']};linenumber={d['line']};columnnumber={d['column']};code={d['rule']}]{d['message']}")
        out = "\n".join(lines)
        if diagnostics:
            out += "\n\n"
        out += format_summary(diagnostics, file_count, elapsed_ms, is_fmt, fixed_count, total_count)
        return out

    elif format_name == "sarif":
        rules_map = {}
        results = []
        for d in diagnostics:
            r = d["rule"]
            if r not in rules_map:
                rules_map[r] = {
                    "id": r,
                    "name": r,
                    "shortDescription": {"text": f"Markdown rule {r}"},
                    "fullDescription": {"text": f"Markdown linting rule {r}"}
                }
            results.append({
                "ruleId": r,
                "level": d.get("severity", "warning"),
                "message": {"text": d["message"]},
                "locations": [{
                    "physicalLocation": {
                        "artifactLocation": {"uri": d["file"]},
                        "region": {"startLine": d["line"], "startColumn": d["column"]}
                    }
                }]
            })
        sarif_doc = {
            "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
            "version": "2.1.0",
            "runs": [{
                "tool": {
                    "driver": {
                        "name": "rumdl",
                        "version": "0.1.13",
                        "informationUri": "https://github.com/rvben/rumdl",
                        "rules": list(rules_map.values())
                    }
                },
                "results": results
            }]
        }
        return json.dumps(sarif_doc, indent=2)

    elif format_name == "junit":
        # JUnit XML
        root = ET.Element("testsuites", name="rumdl", tests="1", failures=str(len(diagnostics)), errors="0", time=f"{elapsed_ms/1000:.3f}")
        ts = ET.SubElement(root, "testsuite", name=diagnostics[0]["file"] if diagnostics else "rumdl", tests="1", failures=str(len(diagnostics)), errors="0", time="0.000")
        tc = ET.SubElement(ts, "testcase", name=f"Lint {ts.attrib['name']}", classname="rumdl", time="0.000")
        for d in diagnostics:
            f = ET.SubElement(tc, "failure", type=d["rule"], message=d["message"])
            f.text = f"{d['message']} at line {d['line']}, column {d['column']}"
        return '<?xml version="1.0" encoding="UTF-8"?>\n' + ET.tostring(root, encoding="utf-8").decode("utf-8")

    return ""

def format_summary(diagnostics, file_count, elapsed_ms, is_fmt=False, fixed_count=0, total_count=0):
    file_str = "file" if file_count == 1 else "files"
    if is_fmt:
        if total_count > 0:
            rem = total_count - fixed_count
            if rem > 0:
                return f"Fixed: Fixed {fixed_count}/{total_count} issues in {file_count} {file_str} ({elapsed_ms}ms)"
            return f"Fixed: Fixed {fixed_count}/{total_count} issues in {file_count} {file_str} ({elapsed_ms}ms)"
        return f"Success: No issues found in {file_count} {file_str} ({elapsed_ms}ms)"
    else:
        if not diagnostics:
            return f"Success: No issues found in {file_count} {file_str} ({elapsed_ms}ms)"
        issue_count = len(diagnostics)
        issue_str = "issue" if issue_count == 1 else "issues"
        fixable = sum(1 for d in diagnostics if d.get("fixable"))
        out = f"Issues: Found {issue_count} {issue_str} in {file_count} {file_str} ({elapsed_ms}ms)"
        if fixable > 0:
            out += f"\nRun `rumdl fmt` to automatically fix {fixable} of the {issue_count} issues"
        return out
EOF"}

