import re
import os
from pathlib import Path

def get_line_offsets(content):
    offsets = [0]
    for i, ch in enumerate(content):
        if ch == '\n':
            offsets.append(i + 1)
    return offsets

def pos_to_offset(line_offsets, line, col):
    # line and col are 1-based
    if line - 1 < len(line_offsets):
        return line_offsets[line - 1] + (col - 1)
    return line_offsets[-1]

def check_file(content, file_path, config, flavor="standard", enabled_rules=None):
    lines = content.splitlines(keepends=True)
    line_offsets = get_line_offsets(content)
    diagnostics = []

    # Parse inline comment states per line
    # States: set of disabled rules per line (or '*' for all)
    line_disabled = [set() for _ in range(len(lines) + 1)] # 1-based index

    # Process inline comments
    in_code_block = False
    stack = []
    global_disabled = set()

    for idx, line in enumerate(lines, 1):
        stripped = line.strip()
        if stripped.startswith("```") or stripped.startswith("~~~"):
            in_code_block = not in_code_block
            continue
        if in_code_block:
            continue

        # Check for prettier-ignore
        if "<!-- prettier-ignore -->" in line:
            if idx + 1 <= len(lines):
                line_disabled[idx + 1].add("*")
            continue

        # Check for rumdl or markdownlint comments
        m = re.search(r'<!--\s*(rumdl|markdownlint)-(disable|enable|disable-next-line|disable-line|disable-file|capture|restore)\b(.*?)-->', line, re.IGNORECASE)
        if m:
            prefix, action, rest = m.group(1).lower(), m.group(2).lower(), m.group(3).strip()
            rules_specified = set(rest.split()) if rest else {"*"}

            if action == "disable":
                global_disabled.update(rules_specified)
            elif action == "enable":
                if "*" in rules_specified:
                    global_disabled.clear()
                else:
                    global_disabled.difference_update(rules_specified)
            elif action == "disable-next-line":
                if idx + 1 <= len(lines):
                    line_disabled[idx + 1].update(rules_specified)
            elif action == "disable-line":
                line_disabled[idx].update(rules_specified)
            elif action == "disable-file":
                for i in range(1, len(lines) + 1):
                    line_disabled[i].update(rules_specified)
            elif action == "capture":
                stack.append(set(global_disabled))
            elif action == "restore":
                if stack:
                    global_disabled = stack.pop()

        if global_disabled:
            line_disabled[idx].update(global_disabled)

    def is_rule_disabled(line_no, rule_code, rule_name):
        d = line_disabled[line_no] if line_no < len(line_disabled) else set()
        if "*" in d or "all" in d:
            return True
        for item in d:
            if item.upper() == rule_code or item.lower() == rule_name.lower():
                return True
        return False

    # Filter enabled rules
    active_rules = set()
    if enabled_rules:
        active_rules = set(enabled_rules)
    else:
        # Default active rules (excluding opt-in rules MD060, MD063, MD072, MD073 unless enabled)
        opt_in = {"MD060", "MD063", "MD072", "MD073"}
        dis = set(config.global_config.get("disable", []))
        for rcode in [f"MD{i:03d}" for i in range(1, 74)]:
            if rcode in opt_in:
                if rcode in config.global_config.get("enable", []) or config.rule_configs.get(rcode, {}).get("enabled"):
                    active_rules.add(rcode)
            else:
                if rcode not in dis:
                    active_rules.add(rcode)

    # Context parsing for file
    headings = [] # (line_no, level, text, start_col, end_col, is_atx, closing_hashes)
    lists = []
    code_blocks = []
    tables = []
    blockquotes = []
    in_fence = False
    fence_char = None
    fence_len = 0

    for idx, line in enumerate(lines, 1):
        raw = line.rstrip("\r\n")
        lstrip = raw.lstrip()

        # Fence
        if lstrip.startswith("```") or lstrip.startswith("~~~"):
            fchar = lstrip[0]
            flen = len(lstrip) - len(lstrip.lstrip(fchar))
            if not in_fence:
                in_fence = True
                fence_char = fchar
                fence_len = flen
                code_blocks.append((idx, idx, fchar, flen, lstrip[flen:].strip()))
            else:
                if fchar == fence_char and flen >= fence_len:
                    in_fence = False
            continue

        if in_fence:
            continue

        # ATX Heading
        if lstrip.startswith("#"):
            hashes = len(lstrip) - len(lstrip.lstrip("#"))
            if hashes <= 6:
                content_part = lstrip[hashes:]
                closing = False
                if content_part.endswith("#") and not content_part.endswith("\\#"):
                    closing = True
                headings.append((idx, hashes, raw, 1, len(raw), True, closing))
                continue

        # Setext Heading
        if idx > 1 and not headings and (lstrip.startswith("===") or lstrip.startswith("---")):
            if all(c in "=-" for c in lstrip):
                prev_line = lines[idx-2].rstrip("\r\n")
                if prev_line.strip():
                    lvl = 1 if lstrip.startswith("=") else 2
                    headings.append((idx-1, lvl, prev_line, 1, len(prev_line), False, False))
                    continue

    # MD001: heading-increment
    if "MD001" in active_rules and not is_rule_disabled(1, "MD001", "heading-increment"):
        last_lvl = 0
        for h_line, h_lvl, h_text, sc, ec, is_atx, _ in headings:
            if is_rule_disabled(h_line, "MD001", "heading-increment"):
                continue
            if last_lvl > 0 and h_lvl > last_lvl + 1:
                exp = last_lvl + 1
                start_off = pos_to_offset(line_offsets, h_line, 1)
                end_off = start_off + len(lines[h_line-1])
                replacement = f"{'#' * exp} {h_text.lstrip('#').strip()}\n"
                diagnostics.append({
                    "file": file_path, "line": h_line, "column": 1,
                    "rule": "MD001",
                    "message": f"Expected heading level {exp}, but found heading level {h_lvl}",
                    "severity": "error", "fixable": True,
                    "fix": {"range": {"start": start_off, "end": end_off}, "replacement": replacement}
                })
            last_lvl = h_lvl

    # MD004: ul-style
    if "MD004" in active_rules:
        target_style = config.rule_configs.get("MD004", {}).get("style", "consistent")
        first_marker = None
        for idx, line in enumerate(lines, 1):
            if is_rule_disabled(idx, "MD004", "ul-style"):
                continue
            stripped = line.lstrip()
            if stripped and stripped[0] in "*+-" and len(stripped) > 1 and stripped[1] in " \t":
                m = stripped[0]
                if not first_marker:
                    first_marker = m
                exp_m = "*" if target_style == "asterisk" else ("+" if target_style == "plus" else ("-" if target_style == "dash" else first_marker))
                if m != exp_m:
                    col = len(line) - len(stripped) + 1
                    start_off = pos_to_offset(line_offsets, idx, col)
                    diagnostics.append({
                        "file": file_path, "line": idx, "column": col,
                        "rule": "MD004",
                        "message": f"List marker '{m}' does not match expected style '{exp_m}'",
                        "severity": "warning", "fixable": True,
                        "fix": {"range": {"start": start_off, "end": start_off + 1}, "replacement": exp_m}
                    })

    # MD009: no-trailing-spaces
    if "MD009" in active_rules:
        br_spaces = config.rule_configs.get("MD009", {}).get("br-spaces", 2)
        strict = config.rule_configs.get("MD009", {}).get("strict", False)
        for idx, line in enumerate(lines, 1):
            if is_rule_disabled(idx, "MD009", "no-trailing-spaces"):
                continue
            raw = line.rstrip("\r\n")
            trimmed = raw.rstrip(" ")
            spaces = len(raw) - len(trimmed)
            if spaces > 0:
                if not strict and spaces == br_spaces:
                    continue
                col = len(trimmed) + 1
                start_off = pos_to_offset(line_offsets, idx, col)
                end_off = start_off + spaces
                diagnostics.append({
                    "file": file_path, "line": idx, "column": col,
                    "rule": "MD009",
                    "message": f"{spaces} trailing spaces found",
                    "severity": "warning", "fixable": True,
                    "fix": {"range": {"start": start_off, "end": end_off}, "replacement": ""}
                })

    # MD010: no-hard-tabs
    if "MD010" in active_rules:
        spaces_per_tab = config.rule_configs.get("MD010", {}).get("spaces-per-tab", 4)
        for idx, line in enumerate(lines, 1):
            if is_rule_disabled(idx, "MD010", "no-hard-tabs"):
                continue
            if "\t" in line:
                col = line.find("\t") + 1
                start_off = pos_to_offset(line_offsets, idx, col)
                diagnostics.append({
                    "file": file_path, "line": idx, "column": col,
                    "rule": "MD010",
                    "message": "Hard tabs found",
                    "severity": "warning", "fixable": True,
                    "fix": {"range": {"start": start_off, "end": start_off + 1}, "replacement": " " * spaces_per_tab}
                })

    # MD012: no-multiple-blanks
    if "MD012" in active_rules:
        max_blanks = config.rule_configs.get("MD012", {}).get("maximum", 1)
        consecutive = 0
        for idx, line in enumerate(lines, 1):
            if is_rule_disabled(idx, "MD012", "no-multiple-blanks"):
                consecutive = 0
                continue
            if not line.strip():
                consecutive += 1
                if consecutive > max_blanks:
                    start_off = pos_to_offset(line_offsets, idx, 1)
                    end_off = start_off + len(line)
                    diagnostics.append({
                        "file": file_path, "line": idx, "column": 1,
                        "rule": "MD012",
                        "message": f"Multiple consecutive blank lines ({consecutive} > {max_blanks})",
                        "severity": "warning", "fixable": True,
                        "fix": {"range": {"start": start_off, "end": end_off}, "replacement": ""}
                    })
            else:
                consecutive = 0

    # MD013: line-length
    if "MD013" in active_rules:
        limit = config.rule_configs.get("MD013", {}).get("line-length", 80)
        check_headings = config.rule_configs.get("MD013", {}).get("headings", True)
        check_code = config.rule_configs.get("MD013", {}).get("code-blocks", True)
        if limit > 0:
            for idx, line in enumerate(lines, 1):
                if is_rule_disabled(idx, "MD013", "line-length"):
                    continue
                raw = line.rstrip("\r\n")
                if len(raw) > limit:
                    col = limit + 1
                    diagnostics.append({
                        "file": file_path, "line": idx, "column": col,
                        "rule": "MD013",
                        "message": f"Line length {len(raw)} exceeds {limit} characters",
                        "severity": "warning", "fixable": True,
                        "fix": None
                    })

    # MD018: no-missing-space-atx
    if "MD018" in active_rules:
        for idx, line in enumerate(lines, 1):
            if is_rule_disabled(idx, "MD018", "no-missing-space-atx"):
