                        pattern = line.rstrip("/")
                        if fnmatch.fnmatch(rel_str, pattern) or fnmatch.fnmatch(path.name, pattern) or any(fnmatch.fnmatch(p, pattern) for p in parts):
                            return True
        except Exception:
            pass
    return False

def find_markdown_files(paths, config, respect_gitignore=True, force_exclude=False):
    found_files = []
    root_dir = Path.cwd()
    excludes = config.global_config.get("exclude", [])
    includes = config.global_config.get("include", [])

    for p_str in paths:
        p = Path(p_str)
        if p.is_file():
            # Explicit file
            if force_exclude and is_excluded(p, root_dir, excludes):
                continue
            found_files.append(p)
        elif p.is_dir():
            for root, dirs, files in os.walk(p):
                rpath = Path(root)
                # Filter dirs
                if respect_gitignore and is_gitignore_ignored(rpath, root_dir):
                    dirs.clear()
                    continue
                for file in files:
                    fpath = rpath / file
                    if fpath.suffix.lower() in VALID_EXTENSIONS:
                        if respect_gitignore and is_gitignore_ignored(fpath, root_dir):
                            continue
                        if is_excluded(fpath, root_dir, excludes):
                            continue
                        if includes and not is_included(fpath, root_dir, includes):
                            continue
                        found_files.append(fpath)
    return found_files

def is_excluded(path, root_dir, excludes):
    try:
        rel = str(path.relative_to(root_dir))
    except ValueError:
        rel = str(path)
    name = path.name
    for pat in excludes:
        if fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch(name, pat):
            return True
    return False

def is_included(path, root_dir, includes):
    try:
        rel = str(path.relative_to(root_dir))
    except ValueError:
        rel = str(path)
    name = path.name
    for pat in includes:
        if fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch(name, pat):
            return True
    return False

def apply_fixes(content, diagnostics):
    # Sort fixes backwards by start offset to avoid shifting offsets
    fixable = [d for d in diagnostics if d.get("fixable") and d.get("fix")]
    if not fixable:
        return content, 0

    # Sort reverse by range start
    fixable.sort(key=lambda d: d["fix"]["range"]["start"], reverse=True)

    new_content = content
    applied = 0

    for d in fixable:
        fix = d["fix"]
        st = fix["range"]["start"]
        end = fix["range"]["end"]
        rep = fix["replacement"]
        if st <= len(new_content) and end <= len(new_content):
            new_content = new_content[:st] + rep + new_content[end:]
            applied += 1
            d["fixed"] = True

    return new_content, applied
